-- Valida acesso público aos próprios relatos e acesso da equipe só pela lista autorizada.
-- Nenhuma alteração ou atendimento de teste é conservado.
begin;
do $$
declare gestor public.usuarios%rowtype; associado public.usuarios%rowtype; responsavel public.usuarios%rowtype;
 a uuid; b uuid; r jsonb; negou boolean;
begin
 select u.* into gestor from public.usuarios u where status='ativo' and auth_id is not null and exists(select 1 from public.usuario_funcoes uf join public.funcoes f on f.id=uf.funcao_id where uf.usuario_id=u.id and f.nome='Tesoureiro') limit 1;
 select u.* into associado from public.usuarios u where status='ativo' and auth_id is not null and not exists(select 1 from public.usuario_funcoes uf join public.funcoes f on f.id=uf.funcao_id where uf.usuario_id=u.id and f.nome='Tesoureiro') limit 1;
 select u.* into responsavel from public.usuarios u where status='ativo' and auth_id is not null and id not in(gestor.id,associado.id) and not exists(select 1 from public.usuario_funcoes uf join public.funcoes f on f.id=uf.funcao_id where uf.usuario_id=u.id and f.nome='Tesoureiro') limit 1;
 assert gestor.id is not null and associado.id is not null and responsavel.id is not null;
 delete from public.fale_responsaveis where usuario_id in(gestor.id,associado.id,responsavel.id);
 insert into public.fale_responsaveis(usuario_id,criado_por) values(responsavel.id,gestor.id);
 assert not has_table_privilege('authenticated','public.fale_mensagens','SELECT');
 assert not has_function_privilege('anon','public.fale_com_a_gente(text,jsonb)','EXECUTE');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',associado.auth_id,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 r:=public.fale_com_a_gente('acesso');
 assert (r->>'permitido')::boolean and not (r->>'equipe')::boolean and not (r->>'gerenciar')::boolean;
 assert (public.fale_com_a_gente('avisos')->>'equipe')::integer=0;
 a:=(public.fale_com_a_gente('criar','{"assunto":"Teste liberação","categoria":"Outro","texto":"Solicitação do associado"}')->>'id')::uuid;
 negou:=false; begin perform public.fale_com_a_gente('listar','{"equipe":true}'); exception when insufficient_privilege then negou:=true; end; assert negou,'Associado acessou equipe';
 negou:=false; begin perform public.fale_com_a_gente('responsaveis'); exception when insufficient_privilege then negou:=true; end; assert negou,'Associado acessou Gestão APP';
 negou:=false; begin perform public.fale_com_a_gente('salvar_responsaveis','{"usuarios":[]}'); exception when insufficient_privilege then negou:=true; end; assert negou,'Associado alterou permissões';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',gestor.auth_id,'role','authenticated')::text,true);
 r:=public.fale_com_a_gente('acesso'); assert (r->>'gerenciar')::boolean and not (r->>'equipe')::boolean,'Tesoureiro ganhou equipe por cargo';
 perform public.fale_com_a_gente('responsaveis');
 negou:=false; begin perform public.fale_com_a_gente('detalhe',jsonb_build_object('id',a,'equipe',true)); exception when insufficient_privilege then negou:=true; end; assert negou,'Tesoureiro sem seleção leu relato';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',responsavel.auth_id,'role','authenticated')::text,true);
 r:=public.fale_com_a_gente('acesso'); assert (r->>'equipe')::boolean and not (r->>'gerenciar')::boolean;
 negou:=false; begin perform public.fale_com_a_gente('responsaveis'); exception when insufficient_privilege then negou:=true; end; assert negou,'Responsável ganhou Gestão APP';
 r:=public.fale_com_a_gente('detalhe',jsonb_build_object('id',a,'equipe',true)); assert r->'atendimento'->>'situacao'='lido';
 perform public.fale_com_a_gente('mensagem',jsonb_build_object('id',a,'equipe',true,'interna',true,'texto','Anotação sigilosa'));
 perform public.fale_com_a_gente('mensagem',jsonb_build_object('id',a,'equipe',true,'texto','Resposta pública'));
 b:=(public.fale_com_a_gente('criar','{"assunto":"Relato de outro titular","categoria":"Outro","texto":"Outro relato"}')->>'id')::uuid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',associado.auth_id,'role','authenticated')::text,true);
 r:=public.fale_com_a_gente('detalhe',jsonb_build_object('id',a));
 assert r->'atendimento'->>'situacao'='em_acompanhamento';
 assert not (r->'mensagens' @> '[{"tipo":"interna"}]'::jsonb),'Nota interna vazou';
 negou:=false; begin perform public.fale_com_a_gente('detalhe',jsonb_build_object('id',b)); exception when insufficient_privilege then negou:=true; end; assert negou,'Leu relato de outro titular';
 negou:=false; begin perform public.fale_com_a_gente('encerrar',jsonb_build_object('id',a)); exception when insufficient_privilege then negou:=true; end; assert negou,'Associado solicitou encerramento pela equipe';
 perform public.fale_com_a_gente('mensagem',jsonb_build_object('id',a,'texto','Complemento'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',responsavel.auth_id,'role','authenticated')::text,true);
 perform public.fale_com_a_gente('encerrar',jsonb_build_object('id',a,'equipe',true));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',associado.auth_id,'role','authenticated')::text,true);
 perform public.fale_com_a_gente('confirmar',jsonb_build_object('id',a));
 perform public.fale_com_a_gente('avaliar',jsonb_build_object('id',a,'avaliacao','satisfeito'));
 negou:=false; begin perform public.fale_com_a_gente('mensagem',jsonb_build_object('id',a,'texto','Após fechamento')); exception when others then negou:=true; end; assert negou,'Finalizado recebeu mensagem';
 execute 'reset role';
 delete from public.fale_responsaveis where usuario_id=responsavel.id;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',responsavel.auth_id,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 negou:=false; begin perform public.fale_com_a_gente('listar','{"equipe":true}'); exception when insufficient_privilege then negou:=true; end; assert negou,'Revogação não funcionou';
 perform set_config('request.jwt.claims','{}',true);
 negou:=false; begin perform public.fale_com_a_gente('acesso'); exception when insufficient_privilege then negou:=true; end; assert negou,'Acesso sem sessão';
 execute 'reset role';
end $$;
rollback;
select 'Liberação, isolamento por titular, equipe, gestão, revogação e encerramento: OK; testes desfeitos' as resultado;
